{
  "name": "lark",
  "version": "1.0.4",
  "description": "Feishu/Lark workflows for messaging, documents, spreadsheets, calendar, tasks, meetings, and enterprise collaboration.",
  "i18n": {
    "display_name": {
      "en": "Feishu",
      "zh-cn": "飞书",
      "ja": "Feishu"
    },
    "description": {
      "en": "Connect your Feishu account to let TRAE manage docs, bases, calendars, messages and more",
      "zh-cn": "连接你的飞书账号，让 TRAE 操作云文档、多维表格、日历、消息等飞书功能",
      "ja": "Feishu アカウントを接続して、TRAE ドキュメント・テーブル・カレンダー・メッセージなどを操作"
    }
  },
  "author": {
    "name": "Lark",
    "url": "https://www.larksuite.com"
  },
  "homepage": "https://www.larksuite.com",
  "repository": "https://github.com/openai/plugins",
  "license": "MIT",
  "keywords": [
    "lark",
    "feishu",
    "collaboration",
    "documents",
    "spreadsheets",
    "calendar",
    "messaging",
    "tasks",
    "meetings"
  ],
  "binaries": [
    {
      "name": "lark-cli",
      "path": "bin/lark-cli",
      "required": true,
      "executable": true,
      "platforms": {
        "linux-arm64": {
          "sha256": "119ad202e9d534c03ee6f9866722ea2ef5554f7092bbb82d18697f24ab6d32ff",
